// Universal Reference (T&&)
template <typename T>
void f(T&& arg);

// Bind to Lvalue
int x = 10;
f(x); // T deduced as int& (Lvalue reference)

// Bind to Rvalue
f(42); // T deduced as int (Value type)

// Perfect Forwarding implementation
template <typename T>
void wrapper(T&& arg) {
    target(std::forward<T>(arg));
}
